  summary.style.cssText = 'text-align:center; margin-top:8px; font-size:0.9rem; color:#4a5568;';
"""

js += "  summary.innerHTML = 'Min: <strong>$" + f"{s['min_price']:.2f}" + "</strong> &bull; Q1: <strong>$" + f"{s['p25']:.2f}" + "</strong> &bull; Median: <strong>$" + f"{s['median']:.2f}" + "</strong> &bull; Q3: <strong>$" + f"{s['p75']:.2f}" + "</strong> &bull; Max: <strong>$" + f"{s['max_price']:.2f}" + "</strong>';\n"

js += r"""
  container.appendChild(summary);
})();
"""

js += '</script>\n</body>\n</html>'

parts.append(js)

full_html = ''.join(parts)

with open('/app/output/final_report.html', 'w') as f:
    f.write(full_html)

print(f"Report written successfully: {len(full_html)} characters")
